eval("function f(n){var o={pear:3},sum=0,guard=0;for(var i=0;i<n&&guard<23;i++,guard++){sum+=o.pear;o.pear=i+1;}return sum+':'+o.pear;}function g(n){var sum=0,guard=0;for(var i=0;i<n&&guard<23;i++,guard++){var o={pear:i+2};sum+=o.pear;}return sum;}function a(n){var v=[3,5],sum=0,guard=0;for(var i=0;i<n&&guard<23;i++,guard++){sum+=v[0];v[0]=i;}return sum+':'+v[0];}[f(0),f(7),g(0),g(7),a(7)].join('|');\n")
